# ! [doc = " Synchronization objects that employ poisoning."] # ! [doc = ""] # ! [doc = " # Poisoning"] # ! [doc = ""] # ! [doc = " All synchronization objects in this module implement a strategy called"] # ! [doc = " \"poisoning\" where a primitive becomes poisoned if it recognizes that some"] # ! [doc = " thread has panicked while holding the exclusive access granted by the"] # ! [doc = " primitive. This information is then propagated to all other threads"] # ! [doc = " to signify that the data protected by this primitive is likely tainted"] # ! [doc = " (some invariant is not being upheld)."] # ! [doc = ""] # ! [doc = " The specifics of how this \"poisoned\" state affects other threads and whether"] # ! [doc = " the panics are recognized reliably or on a best-effort basis depend on the"] # ! [doc = " primitive. See [Overview](#overview) below."] # ! [doc = ""] # ! [doc = " For the alternative implementations that do not employ poisoning,"] # ! [doc = " see [`std::sync::nonpoison`]."] # ! [doc = ""] # ! [doc = " [`std::sync::nonpoison`]: crate::sync::nonpoison"] # ! [doc = ""] # ! [doc = " # Overview"] # ! [doc = ""] # ! [doc = " Below is a list of synchronization objects provided by this module"] # ! [doc = " with a high-level overview for each object and a description"] # ! [doc = " of how it employs \"poisoning\"."] # ! [doc = ""] # ! [doc = " - [`Condvar`]: Condition Variable, providing the ability to block"] # ! [doc = "   a thread while waiting for an event to occur."] # ! [doc = ""] # ! [doc = "   Condition variables are typically associated with"] # ! [doc = "   a boolean predicate (a condition) and a mutex."] # ! [doc = "   This implementation is associated with [`poison::Mutex`](Mutex),"] # ! [doc = "   which employs poisoning."] # ! [doc = "   For this reason, [`Condvar::wait()`] will return a [`LockResult`],"] # ! [doc = "   just like [`poison::Mutex::lock()`](Mutex::lock) does."] # ! [doc = ""] # ! [doc = " - [`Mutex`]: Mutual Exclusion mechanism, which ensures that at"] # ! [doc = "   most one thread at a time is able to access some data."] # ! [doc = ""] # ! [doc = "   Panicking while holding the lock typically poisons the mutex, but it is"] # ! [doc = "   not guaranteed to detect this condition in all circumstances."] # ! [doc = "   [`Mutex::lock()`] returns a [`LockResult`], providing a way to deal with"] # ! [doc = "   the poisoned state. See [`Mutex`'s documentation](Mutex#poisoning) for more."] # ! [doc = ""] # ! [doc = " - [`Once`]: A thread-safe way to run a piece of code only once."] # ! [doc = "   Mostly useful for implementing one-time global initialization."] # ! [doc = ""] # ! [doc = "   [`Once`] is reliably poisoned if the piece of code passed to"] # ! [doc = "   [`Once::call_once()`] or [`Once::call_once_force()`] panics."] # ! [doc = "   When in poisoned state, subsequent calls to [`Once::call_once()`] will panic too."] # ! [doc = "   [`Once::call_once_force()`] can be used to clear the poisoned state."] # ! [doc = ""] # ! [doc = " - [`RwLock`]: Provides a mutual exclusion mechanism which allows"] # ! [doc = "   multiple readers at the same time, while allowing only one"] # ! [doc = "   writer at a time. In some cases, this can be more efficient than"] # ! [doc = "   a mutex."] # ! [doc = ""] # ! [doc = "   This implementation, like [`Mutex`], usually becomes poisoned on a panic."] # ! [doc = "   Note, however, that an `RwLock` may only be poisoned if a panic occurs"] # ! [doc = "   while it is locked exclusively (write mode). If a panic occurs in any reader,"] # ! [doc = "   then the lock will not be poisoned."] use split_decls_genesis :: ourprelude :: * ; #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: condvar :: Condvar ; #[unstable (feature = "mapped_lock_guards" , issue = "117108")] pub use self :: mutex :: MappedMutexGuard ; #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: mutex :: { Mutex , MutexGuard } ; #[stable (feature = "rust1" , since = "1.0.0")] #[expect (deprecated)] pub use self :: once :: ONCE_INIT ; #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: once :: { Once , OnceState } ; #[unstable (feature = "mapped_lock_guards" , issue = "117108")] pub use self :: rwlock :: { MappedRwLockReadGuard , MappedRwLockWriteGuard } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: rwlock :: { RwLock , RwLockReadGuard , RwLockWriteGuard } ; use crate :: error :: Error ; use crate :: fmt ; #[cfg (panic = "unwind")] use crate :: sync :: atomic :: { Atomic , AtomicBool , Ordering } ; #[cfg (panic = "unwind")] use crate :: thread ; mod condvar ; #[stable (feature = "rust1" , since = "1.0.0")] mod mutex ; pub (crate) mod once ; mod rwlock ; pub (crate) struct Flag { #[cfg (panic = "unwind")] failed : Atomic < bool > , } impl Flag { #[inline] pub const fn new () -> Flag { Flag { #[cfg (panic = "unwind")] failed : AtomicBool :: new (false) , } } #[doc = " Checks the flag for an unguarded borrow, where we only care about existing poison."] #[inline] pub fn borrow (& self) -> LockResult < () > { if self . get () { Err (PoisonError :: new (())) } else { Ok (()) } } #[doc = " Checks the flag for a guarded borrow, where we may also set poison when `done`."] #[inline] pub fn guard (& self) -> LockResult < Guard > { let ret = Guard { #[cfg (panic = "unwind")] panicking : thread :: panicking () , } ; if self . get () { Err (PoisonError :: new (ret)) } else { Ok (ret) } } #[inline] #[cfg (panic = "unwind")] pub fn done (& self , guard : & Guard) { if ! guard . panicking && thread :: panicking () { self . failed . store (true , Ordering :: Relaxed) ; } } #[inline] #[cfg (not (panic = "unwind"))] pub fn done (& self , _guard : & Guard) { } #[inline] #[cfg (panic = "unwind")] pub fn get (& self) -> bool { self . failed . load (Ordering :: Relaxed) } #[inline (always)] #[cfg (not (panic = "unwind"))] pub fn get (& self) -> bool { false } #[inline] pub fn clear (& self) { #[cfg (panic = "unwind")] self . failed . store (false , Ordering :: Relaxed) } } #[derive (Clone)] pub (crate) struct Guard { #[cfg (panic = "unwind")] panicking : bool , } #[doc = " A type of error which can be returned whenever a lock is acquired."] #[doc = ""] #[doc = " Both [`Mutex`]es and [`RwLock`]s are poisoned whenever a thread fails while the lock"] #[doc = " is held. The precise semantics for when a lock is poisoned is documented on"] #[doc = " each lock. For a lock in the poisoned state, unless the state is cleared manually,"] #[doc = " all future acquisitions will return this error."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " use std::sync::{Arc, Mutex};"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let mutex = Arc::new(Mutex::new(1));"] #[doc = ""] #[doc = " // poison the mutex"] #[doc = " let c_mutex = Arc::clone(&mutex);"] #[doc = " let _ = thread::spawn(move || {"] #[doc = "     let mut data = c_mutex.lock().unwrap();"] #[doc = "     *data = 2;"] #[doc = "     panic!();"] #[doc = " }).join();"] #[doc = ""] #[doc = " match mutex.lock() {"] #[doc = "     Ok(_) => unreachable!(),"] #[doc = "     Err(p_err) => {"] #[doc = "         let data = p_err.get_ref();"] #[doc = "         println!(\"recovered: {data}\");"] #[doc = "     }"] #[doc = " };"] #[doc = " ```"] #[doc = " [`Mutex`]: crate::sync::Mutex"] #[doc = " [`RwLock`]: crate::sync::RwLock"] #[stable (feature = "rust1" , since = "1.0.0")] pub struct PoisonError < T > { data : T , #[cfg (not (panic = "unwind"))] _never : ! , } #[doc = " An enumeration of possible errors associated with a [`TryLockResult`] which"] #[doc = " can occur while trying to acquire a lock, from the [`try_lock`] method on a"] #[doc = " [`Mutex`] or the [`try_read`] and [`try_write`] methods on an [`RwLock`]."] #[doc = ""] #[doc = " [`try_lock`]: crate::sync::Mutex::try_lock"] #[doc = " [`try_read`]: crate::sync::RwLock::try_read"] #[doc = " [`try_write`]: crate::sync::RwLock::try_write"] #[doc = " [`Mutex`]: crate::sync::Mutex"] #[doc = " [`RwLock`]: crate::sync::RwLock"] #[stable (feature = "rust1" , since = "1.0.0")] pub enum TryLockError < T > { #[doc = " The lock could not be acquired because another thread failed while holding"] #[doc = " the lock."] #[stable (feature = "rust1" , since = "1.0.0")] Poisoned (#[stable (feature = "rust1" , since = "1.0.0")] PoisonError < T >) , #[doc = " The lock could not be acquired at this time because the operation would"] #[doc = " otherwise block."] #[stable (feature = "rust1" , since = "1.0.0")] WouldBlock , } #[doc = " A type alias for the result of a lock method which can be poisoned."] #[doc = ""] #[doc = " The [`Ok`] variant of this result indicates that the primitive was not"] #[doc = " poisoned, and the operation result is contained within. The [`Err`] variant indicates"] #[doc = " that the primitive was poisoned. Note that the [`Err`] variant *also* carries"] #[doc = " an associated value assigned by the lock method, and it can be acquired through the"] #[doc = " [`into_inner`] method. The semantics of the associated value depends on the corresponding"] #[doc = " lock method."] #[doc = ""] #[doc = " [`into_inner`]: PoisonError::into_inner"] #[stable (feature = "rust1" , since = "1.0.0")] pub type LockResult < T > = Result < T , PoisonError < T > > ; #[doc = " A type alias for the result of a nonblocking locking method."] #[doc = ""] #[doc = " For more information, see [`LockResult`]. A `TryLockResult` doesn't"] #[doc = " necessarily hold the associated guard in the [`Err`] type as the lock might not"] #[doc = " have been acquired for other reasons."] #[stable (feature = "rust1" , since = "1.0.0")] pub type TryLockResult < Guard > = Result < Guard , TryLockError < Guard > > ; #[stable (feature = "rust1" , since = "1.0.0")] impl < T > fmt :: Debug for PoisonError < T > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . debug_struct ("PoisonError") . finish_non_exhaustive () } } #[stable (feature = "rust1" , since = "1.0.0")] impl < T > fmt :: Display for PoisonError < T > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { "poisoned lock: another task failed inside" . fmt (f) } } #[stable (feature = "rust1" , since = "1.0.0")] impl < T > Error for PoisonError < T > { } impl < T > PoisonError < T > { #[doc = " Creates a `PoisonError`."] #[doc = ""] #[doc = " This is generally created by methods like [`Mutex::lock`](crate::sync::Mutex::lock)"] #[doc = " or [`RwLock::read`](crate::sync::RwLock::read)."] #[doc = ""] #[doc = " This method may panic if std was built with `panic=\"abort\"`."] #[cfg (panic = "unwind")] #[stable (feature = "sync_poison" , since = "1.2.0")] pub fn new (data : T) -> PoisonError < T > { PoisonError { data } } #[doc = " Creates a `PoisonError`."] #[doc = ""] #[doc = " This is generally created by methods like [`Mutex::lock`](crate::sync::Mutex::lock)"] #[doc = " or [`RwLock::read`](crate::sync::RwLock::read)."] #[doc = ""] #[doc = " This method may panic if std was built with `panic=\"abort\"`."] #[cfg (not (panic = "unwind"))] #[stable (feature = "sync_poison" , since = "1.2.0")] #[track_caller] pub fn new (_data : T) -> PoisonError < T > { panic ! ("PoisonError created in a libstd built with panic=\"abort\"") } #[doc = " Consumes this error indicating that a lock is poisoned, returning the"] #[doc = " associated data."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " use std::collections::HashSet;"] #[doc = " use std::sync::{Arc, Mutex};"] #[doc = " use std::thread;"] #[doc = ""] #[doc = " let mutex = Arc::new(Mutex::new(HashSet::new()));"] #[doc = ""] #[doc = " // poison the mutex"] #[doc = " let c_mutex = Arc::clone(&mutex);"] #[doc = " let _ = thread::spawn(move || {"] #[doc = "     let mut data = c_mutex.lock().unwrap();"] #[doc = "     data.insert(10);"] #[doc = "     panic!();"] #[doc = " }).join();"] #[doc = ""] #[doc = " let p_err = mutex.lock().unwrap_err();"] #[doc = " let data = p_err.into_inner();"] #[doc = " println!(\"recovered {} items\", data.len());"] #[doc = " ```"] #[stable (feature = "sync_poison" , since = "1.2.0")] pub fn into_inner (self) -> T { self . data } #[doc = " Reaches into this error indicating that a lock is poisoned, returning a"] #[doc = " reference to the associated data."] #[stable (feature = "sync_poison" , since = "1.2.0")] pub fn get_ref (& self) -> & T { & self . data } #[doc = " Reaches into this error indicating that a lock is poisoned, returning a"] #[doc = " mutable reference to the associated data."] #[stable (feature = "sync_poison" , since = "1.2.0")] pub fn get_mut (& mut self) -> & mut T { & mut self . data } } #[stable (feature = "rust1" , since = "1.0.0")] impl < T > From < PoisonError < T > > for TryLockError < T > { fn from (err : PoisonError < T >) -> TryLockError < T > { TryLockError :: Poisoned (err) } } #[stable (feature = "rust1" , since = "1.0.0")] impl < T > fmt :: Debug for TryLockError < T > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { match * self { #[cfg (panic = "unwind")] TryLockError :: Poisoned (..) => "Poisoned(..)" . fmt (f) , #[cfg (not (panic = "unwind"))] TryLockError :: Poisoned (ref p) => match p . _never { } , TryLockError :: WouldBlock => "WouldBlock" . fmt (f) , } } } #[stable (feature = "rust1" , since = "1.0.0")] impl < T > fmt :: Display for TryLockError < T > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { match * self { #[cfg (panic = "unwind")] TryLockError :: Poisoned (..) => "poisoned lock: another task failed inside" , #[cfg (not (panic = "unwind"))] TryLockError :: Poisoned (ref p) => match p . _never { } , TryLockError :: WouldBlock => "try_lock failed because the operation would block" , } . fmt (f) } } #[stable (feature = "rust1" , since = "1.0.0")] impl < T > Error for TryLockError < T > { #[allow (deprecated)] fn cause (& self) -> Option < & dyn Error > { match * self { #[cfg (panic = "unwind")] TryLockError :: Poisoned (ref p) => Some (p) , #[cfg (not (panic = "unwind"))] TryLockError :: Poisoned (ref p) => match p . _never { } , _ => None , } } } pub (crate) fn map_result < T , U , F > (result : LockResult < T > , f : F) -> LockResult < U > where F : FnOnce (T) -> U , { match result { Ok (t) => Ok (f (t)) , #[cfg (panic = "unwind")] Err (PoisonError { data }) => Err (PoisonError :: new (f (data))) , } }